using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. In-memory relational-ish
// store mirroring the ADO.NET object model (no server, deterministic).
public sealed class CjDb
{
    public sealed class CjParameter
    {
        public string Name { get; }
        public object? Value { get; }
        public CjParameter(string name, object? value) { Name = name; Value = value; }
    }

    public sealed class CjCommand
    {
        public string Sql { get; set; } = "";
        public System.Collections.Generic.List<CjParameter> Parameters { get; } = new();
        public CjCommand(string sql) { Sql = sql; }
        public void AddParameter(string name, object? value) => Parameters.Add(new CjParameter(name, value));
    }

    public System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, object?>> Users { get; } = new();
    public System.Collections.Generic.List<string> ExecutedSql { get; } = new();
    public int PendingTransactions;
    // Test hook: fail the Nth insert (1-based; 0 = never), simulating a
    // downstream constraint failure. Like a real engine, the failure
    // ABORTS any open transaction: staged rows discarded.
    public int FailOnInsertNumber;
    private int insertCount;
    private readonly System.Collections.Generic.List<string> staged = new();
    // Rows inserted inside an open transaction: invisible until commit,
    // and lost entirely if the transaction is never committed.
    public int StagedCount => staged.Count;

    public CjCommand CreateCommand(string sql) => new CjCommand(sql);

    public void BeginTransaction() => PendingTransactions++;
    public void CommitTransaction()
    {
        if (PendingTransactions <= 0) return;
        PendingTransactions--;
        if (PendingTransactions == 0)
        {
            // Commit: staged rows become visible.
            foreach (var name in staged)
                Users.Add(new System.Collections.Generic.Dictionary<string, object?> { ["name"] = name });
            staged.Clear();
        }
    }

    // Runs a command. Only SELECT * FROM <table> (optionally WHERE name = @p)
    // and INSERT INTO <table> (name) VALUES (@p) are supported.
    public System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, object?>> ExecuteReader(CjCommand cmd)
    {
        ExecutedSql.Add(cmd.Sql);
        var sql = cmd.Sql.Trim();
        if (sql.StartsWith("SELECT", System.StringComparison.OrdinalIgnoreCase))
        {
            string table = ExtractTable(sql);
            var rows = new System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, object?>>();
            if (sql.Contains("WHERE", System.StringComparison.OrdinalIgnoreCase))
            {
                // Parameterized WHERE: only matches with a bound parameter are honored.
                if (cmd.Parameters.Count == 1 && cmd.Parameters[0].Name == "@name")
                {
                    foreach (var row in Users)
                        if (Equals(row["name"], cmd.Parameters[0].Value)) rows.Add(row);
                }
                else
                {
                    // Non-parameterized WHERE: rejected by the engine (like real
                    // engines reject unsafe literal comparison here).
                    throw new System.InvalidOperationException("unsafe query: unparameterized WHERE");
                }
                return rows;
            }
            foreach (var row in Users) rows.Add(new System.Collections.Generic.Dictionary<string, object?>(row));
            return rows;
        }
        throw new System.InvalidOperationException("ExecuteReader supports SELECT only");
    }

    public int ExecuteNonQuery(CjCommand cmd)
    {
        ExecutedSql.Add(cmd.Sql);
        var sql = cmd.Sql.Trim();
        if (sql.StartsWith("INSERT", System.StringComparison.OrdinalIgnoreCase))
        {
            if (cmd.Parameters.Count != 1 || cmd.Parameters[0].Name != "@name")
                throw new System.InvalidOperationException("INSERT requires @name parameter");
            insertCount++;
            if (FailOnInsertNumber > 0 && insertCount >= FailOnInsertNumber)
            {
                FailOnInsertNumber = 0;
                staged.Clear();
                PendingTransactions = 0;   // engine aborts the open transaction
                throw new System.InvalidOperationException("constraint violation: insert failed");
            }
            if (PendingTransactions == 0)
            {
                Users.Add(new System.Collections.Generic.Dictionary<string, object?> { ["name"] = cmd.Parameters[0].Value });
            }
            else
            {
                staged.Add((string)cmd.Parameters[0].Value!);
            }
            return 1;
        }
        throw new System.InvalidOperationException("ExecuteNonQuery supports INSERT only");
    }

    private static string ExtractTable(string sql)
    {
        var parts = sql.Split(' ', System.StringSplitOptions.RemoveEmptyEntries);
        int idx = System.Array.FindIndex(parts, p => p.Equals("FROM", System.StringComparison.OrdinalIgnoreCase));
        return idx >= 0 && idx + 1 < parts.Length ? parts[idx + 1] : "?";
    }
}

